inputs.script:
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const box = () => document.querySelector('#cnrResults');
const isoDate = (s) => { const m = String(s || '').match(/(\d{2})[-./](\d{2})[-./](\d{4})/); return m ? m[3] + '-' + m[2] + '-' + m[1] : ''; };
const PDF_RE = /\.pdf($|[?#])|view-pdf|get-pdf/i;

const readPage = (page) => {
  const root = box();
  const table = root && root.querySelector('table');
  const heads = table ? Array.from(table.querySelectorAll('thead th')).map((th) => norm(th.textContent)) : [];
  const rows = [];
  if (table) {
    for (const tr of table.querySelectorAll('tbody > tr')) {
      const tds = Array.from(tr.children).filter((c) => c.tagName === 'TD');
      if (!tds.length || (tds.length === 1 && tds[0].colSpan > 1)) continue;
      const cells = {};
      tds.forEach((td, i) => { cells[heads[i] || td.getAttribute('data-th') || 'col' + i] = norm(td.innerText); });
      const pick = (re) => { const k = Object.keys(cells).find((h) => re.test(h)); return k ? cells[k] : ''; };
      const anchors = Array.from(tr.querySelectorAll('a[href]'));
      const links = anchors.map((a) => a.getAttribute('href'));
      // Judgment cell: English PDF, regional PDFs, then INSC citation links to /pdfdate/. Prefer the English PDF.
      const pdfs = anchors.filter((a) => PDF_RE.test(a.getAttribute('href')) && !/pdfdate/i.test(a.getAttribute('href')));
      const pdf = pdfs.find((a) => /\(English\)/i.test(a.textContent)) || pdfs[0];
      const parties = pick(/petitioner|part(y|ies)|title|cause/i);
      const split = parties.split(/\s+(?:vs\.?|versus|v\/s)\s+/i);
      rows.push({
        pdf_url: pdf ? pdf.getAttribute('href') : '',
        petitioner: split.length > 1 ? split[0] : parties,
        respondent: pick(/^(?!.*petitioner).*respondent/i) || (split.length > 1 ? split.slice(1).join(' Vs ') : ''),
        case_number: pick(/case\s*(no|num)/i),
        diary_number: pick(/diary/i),
        decision_date: isoDate(pick(/date/i) || pick(/^judg(e)?ments?$/i)),
        listed_text: norm(tr.innerText),
        cells_json: JSON.stringify(cells),
        all_links: links.join(' '),
        page: page
      });
    }
  }
  const pager = document.querySelector('#paginationHtml');
  return { rows, html: (root ? root.outerHTML : '') + '\n' + (pager ? pager.outerHTML : '') };
};

const s = window.__sci_listing || (window.__sci_listing = { page: 1, rows: [], pages_html: [], status: '', message: '' });
if (!s.status) {
  const root = box();
  const nf = root && root.querySelector('.notfound');
  if (nf && !root.querySelector('table')) {
    const msg = norm(nf.textContent);
    s.message = msg;
    s.status = /captcha/i.test(msg) ? 'captcha_wrong'
      : /no\s+(record|data|result|judg)|nothing found|not found/i.test(msg) ? 'empty'
      : 'error';
    if (s.status === 'empty') s.pages_html.push(root.outerHTML);
    s.done = true;
  } else {
    const first = readPage(1);
    s.rows.push(...first.rows);
    s.pages_html.push(first.html);
    s.status = 'ok';
  }
}

// Page through the site's own pagination links until none is left or the eval budget runs out.
const deadline = Date.now() + 95000;
while (!s.done && Date.now() < deadline) {
  const next = document.querySelector('#paginationHtml .pagination a[data-page-id="' + (s.page + 1) + '"]');
  if (!next) { s.done = true; break; }
  const before = box().innerHTML;
  next.click();
  const waitUntil = Date.now() + 30000;
  while (Date.now() < waitUntil && box().innerHTML === before) await sleep(300);
  await sleep(500);
  if (box().innerHTML === before) { s.status = 'error'; s.message = 'page ' + (s.page + 1) + ' did not load'; s.done = true; break; }
  const nf = box().querySelector('.notfound');
  if (nf && !box().querySelector('table')) { s.status = 'error'; s.message = 'page ' + (s.page + 1) + ': ' + norm(nf.textContent); s.done = true; break; }
  s.page += 1;
  const p = readPage(s.page);
  s.rows.push(...p.rows);
  s.pages_html.push(p.html);
}

return {
  status: s.status,
  message: s.message,
  complete: !!s.done,
  page_count: s.pages_html.length,
  row_count: s.rows.length,
  // A JSON string, because the result serializer cuts arrays to 50 items (background.ts serialize).
  rows_json: JSON.stringify(s.rows),
  pages_html: s.pages_html
};
